    expect_end, real_start, real_end, status, create_time
)
VALUES (
           #{patientCardId}, #{doctorId}, #{outTradeNo}, #{amount},
           #{paymentStatus}, #{prepayId}, NULL, STR_TO_DATE(#{expectStart}, '%Y-%m-%d %H:%i:%s'),
           STR_TO_DATE(#{expectEnd}, '%Y-%m-%d %H:%i:%s'), NULL, NULL, 1, CURRENT_TIMESTAMP
       );

