UPDATE patient_video_diagnosis
SET payment_status = 3
WHERE payment_status = 1

    AND id = #{id}


    AND TIMESTAMPDIFF(SECOND, create_time, NOW()) >= #{timer}

UPDATE HOSPITAL.VIDEO_DIAGNOSE
SET transaction_id = #{transactionId},
    payment_status = #{paymentStatus}
WHERE out_trade_no = #{outTradeNo}

UPDATE patient_video_diagnosis
SET status = #{status}

    , real_start = STR_TO_DATE(#{realStart}, '%Y-%m-%d %H:%i:%s')


    , real_end = STR_TO_DATE(#{realEnd}, '%Y-%m-%d %H:%i:%s')

WHERE id = #{id}
